targets.query:
WITH latest AS (
  SELECT time, hostname, interface_name, interface_description, admin_status, operational_status, interface_speed_bps, in_errors, out_errors, in_discards, out_discards,
         ROW_NUMBER() OVER (PARTITION BY hostname, interface_name ORDER BY time DESC) AS rn
  FROM fortigate_interfaces
  WHERE time >= now() - INTERVAL ${time_range:sqlstring}
    AND customer LIKE ${customer:sqlstring}
    AND site LIKE ${site:sqlstring}
    AND hostname LIKE ${device:sqlstring}
)
SELECT hostname, interface_name, interface_description,
       CASE WHEN admin_status = 1 THEN 'up' WHEN admin_status = 2 THEN 'down' ELSE 'unknown' END AS admin_status,
       CASE WHEN operational_status = 1 THEN 'up' WHEN operational_status = 2 THEN 'down' WHEN operational_status = 7 THEN 'lower-layer-down' ELSE 'unknown' END AS operational_status,
       interface_speed_bps AS speed_mbps, in_errors, out_errors, in_discards, out_discards, time AS last_collection_time
FROM latest
WHERE rn = 1
ORDER BY hostname, interface_name

